package net.civeira.phylax.features.access.tenantloginprovider.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class SamlIdpEntityIdVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property saml idp entity id of tenant login provider ")
  void test_saml_idp_entity_id_v_o_builder() {
    Assertions.assertFalse(SamlIdpEntityIdVO.nullValue().getSamlIdpEntityId().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(SamlIdpEntityIdVO.tryFrom(null).getSamlIdpEntityId().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", SamlIdpEntityIdVO.from("one").getSamlIdpEntityId().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> SamlIdpEntityIdVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", SamlIdpEntityIdVO.from("one").toString());
  }
}
